#!/usr/bin/env python3
"""Batch genmedia call for task p4-env-concept-sb1: one true-orthographic layout_top.png per scene (--n 1),
and a prompts.json record next to each image. Usage: python3 code/p4-env-concept-sb1_gen.py [SCN-id ...]"""
import json, subprocess, sys, datetime
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor

PROJ = Path(__file__).resolve().parents[1]
BACKEND = Path("/Applications/VideoAgents.app/Contents/Resources/backend")
TASK = "p4-env-concept-sb1"
style = json.loads((PROJ / "bible/style.json").read_text())
STYLE = style["style_fragment_ui"]
NEG = style["negative_prompt_en"]
NEG_WAKE = style["negative_prompt_waking_addon_en"]

PROJECTION = (
    "Projection: true orthographic top-down plan view, camera axis exactly perpendicular to the ground, telecentric, "
    "infinitely far directly overhead, no perspective and no parallax; no wall face, no elevation, no facade and no side "
    "of any object is visible; only the floor or ground plane, the top edges and thickness of walls and the top surfaces "
    "of objects are seen. Every wall line runs parallel to the frame edges, no line converges to a vanishing point, each "
    "wall is a strip of constant width, the same element has the same size anywhere in the frame. The image is filled "
    "edge to edge, no black background, no vignette, no border, not a model floating on a background. Soft even light, "
    "objects cast almost no shadow that would reveal their height. No people, no animals, no text, no labels, no arrows."
)
NEG_TOP = (
    "people, person, human figure, child, girl, woman, animal, rabbit, bird, text, label, arrow, map legend, "
    "door lying on the floor, window lying on the floor, wall elements projected onto the floor, elevation view of a door, "
    "missing wall, open side, dollhouse cutaway, tilted camera, oblique aerial view, three-quarter aerial view, "
    "perspective view, vanishing point, visible wall face, visible facade, architectural scale model, diorama, "
    "black background, pillarbox, letterbox, black bars, border frame, eye-level view"
)
DREAM = ("Dream register: grand weathered Art Nouveau set after Alphonse Mucha, aged, damp, mossy and gilded, "
         "cool verdigris-teal and slate-grey ambience with aged pastel sage, lilac, dusty-rose and tarnished-gold accents.")
WAKE = ("Waking register: plain period realism, hot drowsy July afternoon near Oxford in 1862, lush natural greens, "
        "meadow wildflowers, nothing stylised, no ornament.")

S = {}
S["SCN-falling-dream"] = ("dream", """Scene: looking straight down a deep vertical round well shaft about 2.4 m across, seen as one perfect circle centred in the frame; the circle spans about 85 percent of the frame height, from near the top edge to near the bottom edge, and the middle of the circle is a deep black void falling away into darkness. The shaft wall is a thick ring of soot-dark red brick banded with pastel-and-gold mosaic of flowing vines and poppies. Fixed against the inside of the ring and seen only as their top surfaces from above: on the right (east) side a curved band of dark mahogany cupboard tops with small brass details; on the left (west) side a curved band of stained-pine bookshelf tops showing the tops of rows of old books; at lower right (south-east) a pantry shelf top with round stoneware jar lids, one glass jar and a small saucer of milk; at lower left (south-west) the top rollers of rolled schoolroom maps on verdigris wrought-iron whiplash brackets; at upper right (north-east) the top edges of small oval picture frames on iron brackets; at upper left (north-west) a small round stained-glass roundel set flush into the ring, catching warm light. At the top centre, a near-level earth tunnel laced with hawthorn roots comes in from the top edge of the frame and meets the ring. Outside the ring, solid packed earth and brick fill the rest of the frame to all four edges. A dim warm amber glow from above lights the ring; the centre falls to black.""")
S["SCN-long-hall"] = ("dream", """Scene: a long, low, windowless Art Nouveau stone hall seen from directly above with its roof removed, lying horizontally across the whole frame: the hall floor is one long rectangle from the left edge (north end) to the right edge (south end), filling the middle band of the frame from 35 percent to 65 percent down. The floor is worn honey-coloured limestone flags about 60 cm square, slightly dished along the centre, edged along both long walls by a narrow pastel-and-gold mosaic border of flowing vine tesserae. The two long walls are continuous thick honey-limestone wall lines along the top and bottom edges of the floor; in each wall line twelve evenly spaced shallow notches, each filled flush with dark oak; one more notch in the middle of the right-hand end wall. At the lower left, just in from the left end, a wide gap in the bottom wall line opens into a dark narrow passage running down to the bottom edge of the frame. The left end wall is a solid thick wall line. On the centre line, a row of eleven small round pastel-glass lamp tops, evenly spaced along the hall, each at the centre of a round warm amber pool of light on the floor, darker between the pools. About two-thirds of the way from the left, on the centre line, a small round clear glass table top about 50 cm across with a tiny gold key on it. Against the top wall line, about 79 percent from the left, a low faded crimson curtain lies as a thin strip hugging the base of the wall between two notches. Outside the hall the rest of the frame above and below is solid dark masonry, filled to all edges.""")
S["SCN-little-door-passage"] = ("dream", """Scene, true scale, a close plan: at the right of the frame a strip of the long hall's worn limestone flag floor with a pastel-and-gold mosaic vine border, bounded on its left by the hall's thick honey-limestone wall running vertically from the top edge to the bottom edge at about 78 percent from the left; two dark-oak notches in that wall line, one near the top edge and one near the bottom edge; a low crimson curtain drawn back lies as a thin strip along the base of that wall at the middle. Through the middle of that wall, at exactly half the frame height, a very narrow straight stone passage only about one tenth of the frame height wide runs horizontally left from the wall to about 12 percent from the left edge; its floor is pale limestone flags with a thin mosaic vine border on both sides, the tops of slender verdigris iron ribs crossing it at intervals, a few pink rose petals scattered near its left end. Above and below the passage, solid honey-limestone masonry fills the frame. At the left end the passage opens through a thick wall into a sunlit garden strip along the left edge of the frame: climbing rose bushes with pink blooms at the upper left, white lilies and sweet peas at the lower left, pale gravel between them in bright white daylight. The garden end is bright daylight, the hall end warm amber lamplight.""")
S["SCN-shaft-landing-passage"] = ("dream", """Scene: an underground dream passage seen from directly above with its roof removed. At the right of the frame, centred about 90 percent from the left and 56 percent down, a round earth-floored chamber about one fifth of the frame height across, its packed earth floor holding a heap of dry sticks and curled brown dead leaves; pale hawthorn roots trail along the chamber's upper rim. From the chamber's left side a straight narrow passage about one twelfth of the frame height wide runs horizontally left at 56 percent down to about 7 percent from the left edge: the right third has a raw red-brown earth floor with root tendrils along its edges; the middle third has a packed earth floor between the top edges of red brick side walls, the tops of verdigris cast-iron whiplash ribs crossing it at intervals; the left third has worn limestone flag floor edged by a thin pastel-and-gold vine mosaic border. At the left end the passage turns at a right angle and runs straight up a short leg to about 30 percent down, where it opens into the corner of a lamp-lit limestone-flagged hall floor glowing warm amber at the top-left corner of the frame. Everything else in the frame is solid dark earth and brick to all four edges. Near darkness around the chamber, the warm amber glow increasing toward the top-left corner.""")
S["SCN-pool-of-tears"] = ("dream", """Scene: the long, low Art Nouveau stone hall of the dream seen from directly above with its roof removed, now flooded. The hall floor is one long rectangle lying horizontally across the whole frame from the left edge (north end) to the right edge (south end), filling the middle band from 35 percent to 65 percent down. It is covered by clear, faintly aqua-green still salt water through which the limestone flags and the pastel-and-gold vine mosaic border along both walls show. The two long walls are continuous thick honey-limestone wall lines along the top and bottom of the water, each with twelve evenly spaced notches filled flush with dark oak, dark wet tide-lines at the wall bases. At the lower left, just in from the left end, a wide gap in the bottom wall line lets the water run into a dark narrow passage toward the bottom edge. On the centre line about two-thirds from the left, a small round clear glass table top standing in the water. At the right end, three broken stone steps rise out of the water across the full width of the hall, grass and reeds growing through their joints, with a clump of reeds in the water at the upper right just before the steps. Floating on the water left of the table: a large white folding fan a little above the centre line, a pair of small white kid gloves a little below it. Warm amber reflections of the lamps overhead lie as round gold glints spaced along the centre of the water, with faint ripple rings. Outside the hall, solid dark masonry fills the frame above and below to all edges.""")
S["SCN-pool-bank"] = ("dream", """Scene: an open-air dream shore on a hot summer afternoon seen from directly above, the ground filling the whole frame and continuing beyond all four edges. The left sixth of the frame is still pool water, pale green-aqua, with round white water-lily pads and flowers floating at the upper left. Along the waterline, curving drifts of tall reeds and bulrushes, dense at the upper left and the lower left; between them, at the left of centre, a stretch of trampled dark wet mud covered in footprints. A single long fallen willow trunk lies north-south along the shore, left of centre in the lower half, its limbs sweeping in S-curves. The centre and right of the frame are a level grassy flat of short dry summer grass with daisies and buttercups, purple loosestrife and cream meadowsweet near the reeds. Centred at about 60 percent from the left, a rough circle scuffed into the grass as a worn earth ring about 44 percent of the frame height across, marked with a few upright sticks, reading like a halo roundel. Along the right edge, the dense green canopy tops of a wood. No buildings, no paths, no built ornament; the Art Nouveau feeling lives only in the flowing curves of reeds, lilies and the fallen trunk.""")
S["SCN-riverbank"] = ("waking", """Scene: an English midsummer river bank near Oxford on 4 July 1862 seen from directly above, the ground filling the whole frame and continuing beyond all four edges. The left fifth of the frame is a still, dark-green backwater with round water-lily pads at the upper left and a thick bed of tall reeds and reedmace along its edge at the lower left. The waterline runs from the top edge to the bottom edge at about 22 percent from the left; just right of it a short strip of bare trodden earth and exposed roots marks the lip of the bank at about 30 percent. Right of that, a flat grassy shelf thick with daisies at the centre-left, in open shade. Tree crowns seen from above: the round head of thin shoots of a pollarded willow at the upper left, leaning over the water; a large elm crown at the upper centre-left; another elm crown at the lower centre-left; the grassy shelf between the two elms stays uncovered and visible. A few brown dead leaves on the grass. The right half of the frame is open, sunlit, uncut meadow of long grass with buttercups and daisies, a faint trodden line through it toward the upper right edge. No buildings, no fences, no paths, no boats.""")
S["SCN-field-hedge-burrow"] = ("waking", """Scene: the edge of an English hay meadow in July 1862 seen from directly above, the ground filling the whole frame and continuing beyond all four edges. The upper three-quarters of the frame is long uncut meadow grass with daisies, buttercups and dry seed-heads, with a faint trampled running line coming down through it from the top edge to the hedge. From about 80 to 88 percent down, a laid hawthorn hedge runs horizontally across the full width of the frame as a dense dark-green band of leafy tops with hazel binders woven along it; a narrow band of shade and a shallow dry ditch lie along its upper (field) side. At the hedge foot, about 55 percent from the left, the dark oval opening of an ordinary rabbit burrow about 20 cm across, with a small fan of pale dug earth spreading into the grass above it. At about 32 percent from the left, a short gap in the hedge closed by a weathered grey oak field gate, seen from above only as a thin straight top rail across the gap. At about 80 percent from the left, the round green crown of an oak tree rising out of the hedge line. Below the hedge, along the bottom edge, a strip of ploughed farmland.""")

def run(sid):
    reg, body = S[sid]
    prompt = f"{body}\n{DREAM if reg == 'dream' else WAKE}\n{PROJECTION}\nStyle: {STYLE}"
    neg = f"{NEG}, {NEG_TOP}" + (f", {NEG_WAKE}" if reg == "waking" else "")
    out = PROJ / f"assets/concepts/scenes/{sid}/layout_top.png"
    cmd = ["python3", "modules/genmedia.py", "image", "--prompt", prompt, "--negative", neg,
           "--output", str(out), "--size", "2560x1440", "--n", "1"]
    t0 = datetime.datetime.now().isoformat(timespec="seconds")
    p = subprocess.run(cmd, cwd=BACKEND, capture_output=True, text=True, timeout=1500)
    log = (p.stdout + "\n" + p.stderr).strip()
    (PROJ / f"runs/{TASK}/gen_{sid}.log").write_text(log)
    rec = {
        "task_id": TASK, "scene_id": sid, "generated": t0, "tool": "modules/genmedia.py image",
        "provider_model": "volcengine doubao-seedream-5-0-pro-260628 (genmedia info)",
        "register": reg, "size": "2560x1440", "n": 1, "ref": [],
        "user_refs": [{"path": "refs/style/alice.jpeg", "use": "read as look reference; applied through style_fragment_ui and the dream register text (palette, materials, Mucha ironwork/mosaic/roundels); NOT injected as --ref into this plan view, because an eye-level perspective ref with figures pulls the camera off nadir and adds people/creatures (see result.json)"}] if reg == "dream" else
                     [{"path": "refs/style/alice.jpeg", "use": "not injected: waking register carries no Art Nouveau ornament (CR-014, style_anchors_by_register); only palette discipline applies"}],
        "outputs": ["layout_top.png"] if p.returncode == 0 and out.exists() else [],
        "exit_code": p.returncode,
        "prompt": prompt, "negative": neg,
    }
    (PROJ / f"assets/concepts/scenes/{sid}/prompts.json").write_text(json.dumps(rec, ensure_ascii=False, indent=2))
    return sid, p.returncode, log[-600:]

if __name__ == "__main__":
    ids = sys.argv[1:] or list(S)
    with ThreadPoolExecutor(max_workers=4) as ex:
        for sid, rc, tail in ex.map(run, ids):
            print(f"== {sid} rc={rc}\n{tail}\n")
